using System;using System.Globalization;using RouteTrackerCommander;
class NameCompatibilityTests {
 static int checks;static void A(bool b,string m){checks++;if(!b)throw new Exception(m);}
 static int Main(){var original=CultureInfo.CurrentCulture;try{foreach(string culture in new[]{"en-US","pl-PL","tr-TR"}){CultureInfo.CurrentCulture=CultureInfo.GetCultureInfo(culture);A(RouteSystemNames.Equal("HIP 6011","hip 6011"),"Case-insensitive system comparison");A(!RouteSystemNames.Equal("Sol","Sol A"),"Different names stay different");A(!RouteSystemNames.Equal(null,null),"Null comparison retains former extension behavior");A(!RouteSystemNames.Equal("Sol",null),"Null target is rejected");A(RouteSystemNames.WithoutSystemPrefix("Sol A 1","sol")=="A 1","Body prefix removed ignoring case");A(RouteSystemNames.WithoutSystemPrefix("Sol","Sol")=="Sol","Exact system name retained");A(RouteSystemNames.WithoutSystemPrefix("Alpha A","Sol")=="Alpha A","Unrelated body retained");A(RouteSystemNames.WithoutSystemPrefix("Sol   A 1 ","Sol")=="A 1 ","Only leading whitespace removed");A(RouteSystemNames.WithoutSystemPrefix("Sol A",null)=="Sol A","Unknown prefix retained");}Console.WriteLine("PASS "+checks+" name/prefix compatibility assertions");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}finally{CultureInfo.CurrentCulture=original;}}
}